Future prosesDataOverlay(BuildContext context) async {
  final loader = LoadingWidget.init(context, 'Mempersiapkan data...').show();

  try {
    await Future.delayed(const Duration(seconds: 2));
    loader.message('Mengunduh aset dari server...');
    await Future.delayed(const Duration(seconds: 2));
  } catch (e) {
    print('Error: $e');
  } finally {
    loader.close();
  }
}

// --- CONTOH 2: MODE DEKLARATIF (LOADING ABADI / KONTROL EKSTERNAL) ---
Widget buildStaticLoading(bool isLoading) {
  if (isLoading) {
    return LoadingWidget.widget(
      message: 'Memuat data...',
      size: LoadingSize.sm,
      theme: LoadingTheme.horizontal,
    );
  }
  return const Text('Data Berhasil Dimuat dari Luar!');
}

