// Mengolah Datanya & Menerima Kepingan Chunk
const { Chunk } = require('./Chunk');

io.on('connection', (socket) => {
  console.log('Klien terkoneksi:', socket.id);

  // Inisiasi Handler Engine untuk File Besar (Misal: Video/Dokumen)
  const uploadEngine = new Chunk('UPLOAD_BIG_DATA', socket, {
    maxSize: 50 * 1024 * 1024, // Batasi penerimaan maskimal 50MB
    saveDir: path.join(__dirname, 'storage_data') // Otomatis bikin folder ini jika belum ada
  });

  // Cara Mengolah Datanya Setelah 100% Dirakit Server
  uploadEngine.done((result, transferId) => {
    if (result.status && result.isFile) {
      console.log('Mantap! File berhasil di-reassembly di lokasi disk:', result.data);
      // Aksi Database: Disini Anda bisa simpan 'result.data' path lokal ini ke MySQL/MongoDB
    } else if (result.status && !result.isFile) {
       console.log('Menerima String/JSON Utuh dari klien:', result.data);
       // Aksi Database: Lakukan batch-insert JSON object ini
    }
  });
});


