// Cara Menggunakan SocketHelper & Menyuplai Data ke Server
import 'dart:io';
import 'socket_helper.dart';

void main() async {
  // 1. Hubungkan Flutter SocketHelper ke endpoint Node.js kita
  await SocketHelper.connect('https://ws.uinmadura.ac.id', token: 'jwt-auth-token');

  // 2. Siapkan file masif berukuran besar
  File hugeFile = File('/storage/emulated/0/Download/presentasi_proyek.mp4');

  try {
    // 3. Panggil chunking engine untuk menembakkan potongan data sekuensial
    final response = await SocketHelper.sendChunk(
      'UPLOAD_BIG_DATA',
      hugeFile, 
      onProgress: (double percent) {
        // Perbarui state UI Loading Bar
        print('Mengunggah... ${percent.toStringAsFixed(1)}% selesai');
      }
    );

    print('Pengunggahan selesai, respons backend: $response');
  } catch (err) {
    print('Pengunggahan dibatalkan/Gagal karena: $err');
  }
}

